insert into public.units (id, name, short_name) values
  (1, 'La empresa', 'U1 · Empresa'),
  (2, 'Los jóvenes emprendedores', 'U2 · Emprendedores'),
  (3, 'Generando mi idea de negocio', 'U3 · Idea'),
  (4, 'Mi primer prototipo', 'U4 · Prototipo'),
  (5, 'Costos de mi producto', 'U5 · Costos'),
  (6, 'Estrategias para vender', 'U6 · Ventas'),
  (7, 'Presentando mi producto', 'U7 · Presentación')
insert into public.practice_config (id, time_limit_minutes, question_count, passing_score)
insert into public.questions (legacy_id, unit_id, type, scenario, example, image, stem, options, correct_index, explanation) values
  ('q1', 1, 'concepto', null, null, 'tienda', 'Según su cantidad de trabajadores, una empresa con 25 personas contratadas se clasifica como:', '["Microempresa","Pequeña empresa","Mediana empresa"]'::jsonb, 1, 'La pequeña empresa tiene entre 6 y 30 trabajadores; 25 personas cae en ese rango.'),
  ('q2', 1, 'concepto', null, null, null, '¿Cuál de los siguientes es un recurso financiero de la empresa?', '["La maquinaria de producción","El conocimiento técnico del equipo","El dinero disponible en caja"]'::jsonb, 2, 'Los recursos financieros son el dinero y los medios de pago con que cuenta la empresa para operar.'),
  ('q3', 1, 'caso', 'Un grupo de jóvenes en Cartago ofrece lavar autos a domicilio los sábados.', null, null, '¿A qué tipo de empresa, según su actividad, pertenece este emprendimiento?', '["Industrial","Comercial","De servicios"]'::jsonb, 2, 'Lavar autos no produce ni vende un bien físico: es una actividad de servicios.'),
  ('q4', 1, 'concepto', null, null, null, '¿Cuál es una función principal del empresario dentro de la empresa?', '["Fijar los precios del mercado nacional","Organizar los recursos y tomar decisiones para alcanzar los objetivos","Trabajar únicamente en la producción"]'::jsonb, 1, 'El empresario organiza los recursos (materiales, humanos, financieros) y toma las decisiones clave del negocio.'),
  ('q5', 2, 'concepto', null, null, null, '¿Cuál de las siguientes es una característica del perfil emprendedor?', '["Evitar el riesgo a toda costa","Buscar siempre la aprobación de los demás","Ser perseverante ante los obstáculos"]'::jsonb, 2, 'La perseverancia frente a las dificultades es uno de los rasgos centrales del perfil emprendedor.'),
  ('q6', 2, 'caso', 'Cuando el primer prototipo de sus mochilas recicladas se rompió, Fabiola no se rindió: ajustó el diseño y lo volvió a intentar.', null, 'manualidad', '¿Qué valor emprendedor demuestra Fabiola?', '["Creatividad","Perseverancia","Honestidad"]'::jsonb, 1, 'Insistir y mejorar tras un fracaso es una muestra clara de perseverancia.'),
  ('q7', 2, 'concepto', null, null, null, 'Un valor cooperativista que debe practicar un equipo emprendedor JOVEM es:', '["La competencia desleal entre compañeros","La ayuda mutua y el trabajo en equipo","La acumulación individual de ganancias"]'::jsonb, 1, 'El cooperativismo se basa en la ayuda mutua y el trabajo conjunto hacia una meta común.'),
  ('q8', 3, 'caso', 'María y sus compañeras notaron que muchos estudiantes botan botellas plásticas en el colegio, así que decidieron crear maceteros ecológicos con esas botellas para venderlos en la Feria JOVEM.', null, 'reciclaje', '¿Qué elemento clave de una idea de negocio están aplicando principalmente?', '["Reducir costos de producción","Copiar un producto que ya existe en el mercado","Identificar una necesidad real y aportar innovación con enfoque ambiental"]'::jsonb, 2, 'Una buena idea de negocio parte de identificar un problema real y resolverlo con innovación; el enfoque ambiental es un valor central de JOVEM.'),
  ('q9', 3, 'concepto', null, null, 'idea', 'La propuesta de valor de un producto responde principalmente a:', '["Cuánto cuesta producirlo","Qué necesidad del cliente resuelve y por qué elegirlo a él y no a otro","Quién es el dueño de la empresa"]'::jsonb, 1, 'La propuesta de valor explica qué problema resuelve el producto y por qué es la mejor opción para el cliente.'),
  ('q10', 3, 'caso', 'En su comunidad, muchas personas adultas mayores no saben usar aplicaciones para pedir comida. Un grupo de estudiantes decide ofrecerles un servicio telefónico de pedidos a domicilio.', null, null, '¿Qué paso del proceso de generación de ideas están aplicando?', '["Copiar la idea de una aplicación existente","Identificar una necesidad insatisfecha en un grupo específico","Reducir el precio del servicio"]'::jsonb, 1, 'Están partiendo de una necesidad real y desatendida en un grupo concreto de personas.'),
  ('q11', 3, 'concepto', null, null, null, 'Al evaluar varias ideas de negocio, uno de los criterios de selección es:', '["El nombre y el logo que tendrá el producto","La disponibilidad de materia prima y el conocimiento técnico del equipo","La popularidad del producto en otros países"]'::jsonb, 1, 'Contar con materia prima accesible y saber cómo elaborarla son criterios clave para escoger una idea viable.'),
  ('q12', 4, 'concepto', null, null, 'manualidad', 'Un prototipo es:', '["La versión final del producto que ya no se puede cambiar","Una primera versión del producto que permite probar y mejorar la idea","Un dibujo del producto que nunca se llega a construir"]'::jsonb, 1, 'El prototipo es una versión inicial pensada para probarse y mejorarse antes de producir en mayor escala.'),
  ('q13', 4, 'caso', 'Los estudiantes presentaron su primer prototipo de jabón artesanal a un grupo de compañeros y anotaron todos los comentarios sobre el olor y la textura.', null, 'prueba', '¿Qué están haciendo con esos comentarios?', '["Realizando un estudio de mercado","Seleccionando una nueva idea de negocio","Validando y mejorando el prototipo con base en la retroalimentación"]'::jsonb, 2, 'Recoger comentarios sobre el prototipo para ajustarlo es el proceso de validación y mejora.'),
  ('q14', 4, 'concepto', null, null, null, '¿Por qué es importante probar el prototipo antes de producir en mayor cantidad?', '["Para poder venderlo de inmediato a un precio mayor","Porque es un requisito para inscribirse en la feria","Para detectar mejoras y evitar errores costosos más adelante"]'::jsonb, 2, 'Probar temprano permite corregir fallas antes de invertir en una producción más grande.'),
  ('q15', 5, 'caso', 'El equipo de Andrés gastó ₡6 000 en materiales para producir 20 pulseras y quiere ganar ₡200 por unidad.', null, 'dinero', '¿Cuál debe ser el precio de venta de cada pulsera?', '["₡200","₡300","₡500"]'::jsonb, 2, 'Costo unitario = 6 000 ÷ 20 = ₡300; precio de venta = 300 + 200 de ganancia = ₡500.'),
  ('q16', 5, 'concepto', null, null, 'dinero', 'El costo total de un producto incluye:', '["Únicamente el precio de venta","Solo la ganancia esperada","Todos los gastos de materiales, mano de obra y otros necesarios para producirlo"]'::jsonb, 2, 'El costo total suma todo lo invertido para producir el bien o servicio, no solo un componente.'),
  ('q17', 5, 'caso', 'Un grupo gastó ₡4 000 en ingredientes para hacer 10 panes de banano y quiere ganar ₡100 por unidad.', null, null, '¿Cuál debe ser el precio de venta de cada pan?', '["₡400","₡500","₡100"]'::jsonb, 1, 'Costo unitario = 4 000 ÷ 10 = ₡400; precio de venta = 400 + 100 de ganancia = ₡500.'),
  ('q18', 5, 'concepto', null, null, null, 'El costo unitario de un producto se calcula:', '["Multiplicando el precio de venta por la cantidad vendida","Restando la ganancia al precio de venta","Dividiendo el costo total entre la cantidad de unidades producidas"]'::jsonb, 2, 'Costo unitario = costo total ÷ cantidad de unidades producidas.'),
  ('q19', 6, 'concepto', null, null, 'megafono', 'Ofrecer una muestra gratis del producto a los clientes es un ejemplo de:', '["Fijación de precios","Estudio de mercado","Estrategia de promoción para dar a conocer el producto"]'::jsonb, 2, 'La muestra gratis busca que el cliente conozca el producto: es una estrategia de promoción.'),
  ('q20', 6, 'caso', 'Antes de la feria, el equipo de Valeria calculó cuántas unidades necesitaba vender para cubrir sus costos y obtener ganancia, y lo anotó en un documento.', null, 'mercado', '¿Qué herramienta están utilizando?', '["Un plan de ventas con meta y presupuesto","Un estudio de mercado","Un informe final de resultados"]'::jsonb, 0, 'Definir cuánto vender y con qué presupuesto es exactamente un plan de ventas.'),
  ('q21', 6, 'concepto', null, null, null, 'El mercado meta de un producto es:', '["Cualquier persona, sin importar sus características","El grupo específico de personas con más probabilidad de comprar el producto","Únicamente los amigos y familiares del emprendedor"]'::jsonb, 1, 'El mercado meta es el segmento de personas al que realmente le interesa y puede comprar el producto.'),
  ('q22', 6, 'caso', 'Durante una semana, el grupo ofreció "compre dos y lleve tres" en sus llaveros reciclados para aumentar las ventas antes de la feria.', null, null, '¿Qué tipo de estrategia de venta aplicaron?', '["Reducción de costos de producción","Promoción por tiempo limitado / combo","Degustación del producto"]'::jsonb, 1, 'Es una promoción temporal tipo combo, pensada para incentivar la compra en un periodo corto.'),
  ('q23', 7, 'concepto', null, null, 'presentacion', 'El informe final de un proyecto JOVEM debe incluir principalmente:', '["Solo fotografías del producto","Un resumen del proceso, los resultados y los aprendizajes del proyecto","Únicamente la lista de costos y gastos"]'::jsonb, 1, 'El informe final documenta el proceso completo: qué se hizo, qué resultó y qué se aprendió.'),
  ('q24', 7, 'caso', 'El día de la feria, Andrés explicó a los visitantes el problema que resolvía su producto, cómo lo hizo y qué aprendió durante el proceso.', null, 'presentacion', '¿Qué está haciendo Andrés?', '["Realizando una promoción para vender más","Explicando únicamente el precio del producto","Presentando su proyecto de forma clara y completa"]'::jsonb, 2, 'Explicar el problema, la solución y lo aprendido es justamente presentar el proyecto de forma completa.'),
  ('q25', 7, 'concepto', null, null, null, 'Uno de los propósitos principales de una feria como la Feria JOVEM es:', '["Cumplir con una tarea más del curso","Dar a los jóvenes la oportunidad de mostrar y vender su proyecto emprendedor","Elegir al equipo que gastó menos dinero"]'::jsonb, 1, 'La feria es el espacio para mostrar el proyecto al público y practicar la venta real.'),
  ('q26', 7, 'caso', 'Antes de la feria, el equipo practicó varias veces cómo explicar su producto en menos de dos minutos, cuidando el orden de las ideas.', null, null, '¿Qué habilidad están fortaleciendo?', '["El cálculo de costos","El diseño del prototipo","La presentación oral y la comunicación efectiva de su proyecto"]'::jsonb, 2, 'Ensayar cómo explicar el proyecto de forma clara y ordenada fortalece la comunicación y la presentación oral.'),
  ('q27', 1, 'concepto', null, null, null, '¿Cuál de las siguientes opciones es un ejemplo de bien y no de servicio?', '["Una consulta médica","Una camiseta estampada","Un corte de cabello"]'::jsonb, 1, 'Un bien es un producto tangible que se puede tocar, como la camiseta; los otros dos son servicios.'),
  ('q28', 1, 'caso', 'Don Rafael repara bicicletas en su propio taller y trabaja solo, sin empleados.', null, null, 'Según su tamaño, ¿cómo se clasifica el negocio de Don Rafael?', '["Microempresa","Mediana empresa","Gran empresa"]'::jsonb, 0, 'La microempresa tiene entre 1 y 5 trabajadores; Don Rafael trabaja solo.'),
  ('q29', 1, 'concepto', null, null, null, '¿Cuál de los siguientes es un recurso material de una empresa?', '["Las máquinas y herramientas","El dinero en el banco","El conocimiento contable del equipo"]'::jsonb, 0, 'Los recursos materiales son los bienes físicos que usa la empresa, como máquinas y herramientas.'),
  ('q30', 1, 'concepto', null, null, null, 'El manual de procedimientos y los sistemas de control de una empresa son ejemplos de recursos:', '["Humanos","Técnico-administrativos","Financieros"]'::jsonb, 1, 'Los procedimientos y sistemas de control forman parte de los recursos técnico-administrativos.'),
  ('q31', 1, 'caso', 'Una fábrica transforma la leche en queso y yogur para venderlos.', null, 'manualidad', '¿A qué tipo de empresa, según su actividad, pertenece esta fábrica?', '["Comercial","Industrial","De servicios"]'::jsonb, 1, 'Transformar una materia prima (leche) en otro producto es una actividad industrial.'),
  ('q32', 1, 'caso', 'Una familia cultiva café en su finca y lo cosecha para venderlo a un beneficio.', null, null, '¿A qué tipo de empresa, según su actividad, pertenece este negocio familiar?', '["Agropecuaria","Construcción","Comercial"]'::jsonb, 0, 'Cultivar y cosechar productos de la tierra es una actividad agropecuaria.'),
  ('q33', 1, 'concepto', null, null, null, 'Los recursos humanos de una empresa se refieren a:', '["Las personas que trabajan en ella","El dinero disponible en caja","Los edificios y equipos"]'::jsonb, 0, 'Los recursos humanos son las personas que forman parte de la empresa y aportan su trabajo.'),
  ('q34', 1, 'caso', 'Un supermercado compra productos ya elaborados y los revende a sus clientes.', null, 'tienda', '¿A qué tipo de empresa, según su actividad, pertenece este supermercado?', '["Industrial","Comercial","Agropecuaria"]'::jsonb, 1, 'Comprar y revender productos sin transformarlos es una actividad comercial.'),
  ('q35', 1, 'concepto', null, null, null, 'Una empresa con 80 trabajadores se clasifica, según su tamaño, como:', '["Pequeña empresa","Mediana empresa","Gran empresa"]'::jsonb, 1, 'La mediana empresa tiene entre 31 y 100 trabajadores.'),
  ('q36', 1, 'caso', 'Una empresa nacional emplea a 250 personas en distintas sucursales del país.', null, null, 'Según su tamaño, ¿cómo se clasifica esta empresa?', '["Mediana empresa","Gran empresa","Microempresa"]'::jsonb, 1, 'Con más de 100 trabajadores, la empresa se clasifica como gran empresa.'),
  ('q37', 1, 'concepto', null, null, null, 'Planificar las metas y el rumbo de la empresa es una función principal de:', '["El cliente","El empresario","El proveedor"]'::jsonb, 1, 'El empresario es quien define hacia dónde va la empresa y organiza los recursos para lograrlo.'),
  ('q38', 2, 'concepto', null, null, null, 'Informar de manera clara y real los costos y ganancias del proyecto refleja el valor de:', '["La honestidad","La perseverancia","La creatividad"]'::jsonb, 0, 'Actuar con la verdad frente al equipo y los clientes es una muestra de honestidad.'),
  ('q39', 2, 'caso', 'Un equipo decide no inflar el precio de sus productos aunque otros compañeros sí lo hagan, porque prefieren ser justos con sus clientes.', null, null, '¿Qué valor están practicando?', '["Honestidad","Perseverancia","Creatividad"]'::jsonb, 0, 'Actuar con justicia y transparencia frente al cliente, aunque otros no lo hagan, es honestidad.'),
  ('q40', 2, 'concepto', null, null, null, 'Organizar una recolecta para ayudar a otro equipo que perdió su material antes de la feria es un ejemplo de valor:', '["Ambiental","Social","Financiero"]'::jsonb, 1, 'Apoyar a otras personas de la comunidad escolar es una expresión de un valor social.'),
  ('q41', 2, 'concepto', null, null, 'reciclaje', 'Elegir materiales reciclados para el empaque de un producto refleja un valor:', '["Ambiental","Social","Financiero"]'::jsonb, 0, 'Cuidar el impacto del proyecto sobre el ambiente es un valor ambiental, central en la Guía JOVEM.'),
  ('q42', 2, 'concepto', null, null, null, 'Proponer una nueva idea sin que nadie se lo pida es una muestra de:', '["Iniciativa","Responsabilidad","Puntualidad"]'::jsonb, 0, 'Actuar por cuenta propia para aportar algo nuevo es iniciativa.'),
  ('q43', 2, 'caso', 'Faltando una semana para la feria, Kevin propuso él mismo mejorar el empaque del producto sin que el profesor se lo pidiera.', null, null, '¿Qué característica del perfil emprendedor demuestra Kevin?', '["Iniciativa","Perseverancia","Responsabilidad"]'::jsonb, 0, 'Actuar por decisión propia para mejorar el proyecto es una muestra de iniciativa.'),
  ('q44', 2, 'concepto', null, null, null, 'Buscar una solución distinta a la que ya existe en el mercado demuestra:', '["Creatividad","Perseverancia","Honestidad"]'::jsonb, 0, 'Aportar ideas originales frente a lo ya existente es un ejemplo de creatividad.'),
  ('q45', 2, 'concepto', null, null, null, 'Cumplir con los compromisos y tareas asignadas dentro del equipo demuestra:', '["Responsabilidad","Creatividad","Autoconfianza"]'::jsonb, 0, 'Hacerse cargo de las tareas asignadas y cumplirlas es responsabilidad.'),
  ('q46', 2, 'caso', 'El equipo se dividió las tareas: unos consiguieron materiales, otros hicieron el prototipo y otros diseñaron el empaque.', null, 'equipo', '¿Qué valor están aplicando?', '["Trabajo en equipo","Iniciativa","Perseverancia"]'::jsonb, 0, 'Repartirse tareas y colaborar hacia una misma meta es trabajo en equipo.'),
  ('q47', 2, 'concepto', null, null, null, 'Analizar los pros y contras antes de invertir en materiales para un nuevo producto es:', '["Asumir un riesgo calculado","Evitar cualquier riesgo","Actuar sin planificar"]'::jsonb, 0, 'Evaluar la situación antes de decidir es tomar un riesgo de forma calculada, no al azar.'),
  ('q48', 2, 'concepto', null, null, null, 'Creer en la propia capacidad para sacar adelante un proyecto se conoce como:', '["Autoconfianza","Perseverancia","Responsabilidad"]'::jsonb, 0, 'Confiar en las propias capacidades es la autoconfianza, un rasgo del perfil emprendedor.'),
  ('q49', 2, 'caso', 'Aunque su primer producto no se vendió bien, Daniela analizó qué había fallado y ajustó su estrategia para la siguiente feria.', null, null, '¿Qué característica demuestra Daniela?', '["Aprender del error y seguir intentando","Repetir la misma estrategia sin hacer cambios","Cambiar de proyecto ante la primera dificultad"]'::jsonb, 0, 'Analizar un fracaso y ajustar la estrategia es una muestra de perseverancia y aprendizaje.'),
  ('q50', 3, 'concepto', null, null, 'idea', 'La lluvia de ideas es una técnica que sirve para:', '["Generar muchas posibles ideas sin descartarlas de inmediato","Elegir de inmediato la mejor idea sin analizarla","Calcular el precio final del producto"]'::jsonb, 0, 'La lluvia de ideas busca generar la mayor cantidad de opciones posibles antes de evaluarlas.'),
  ('q51', 3, 'caso', 'El equipo escribió en la pizarra todas las ideas que se les ocurrieron, sin importar si parecían buenas o malas, para luego analizarlas juntos.', null, null, '¿Qué técnica están aplicando?', '["Lluvia de ideas","Estudio de costos","Encuesta a posibles clientes"]'::jsonb, 0, 'Anotar todas las ideas posibles sin filtrarlas de inmediato es una lluvia de ideas.'),
  ('q52', 3, 'concepto', null, '¿De verdad nos entusiasma este proyecto?', null, 'Al elegir una idea de negocio, hacerse esta pregunta corresponde al criterio de:', '["Motivación del equipo","Innovación de la idea","Mercado del producto"]'::jsonb, 0, 'Evaluar el interés real del equipo por la idea corresponde al criterio de motivación.'),
  ('q53', 3, 'concepto', null, null, null, 'Preguntarse si la idea aporta algo diferente a lo que ya existe corresponde al criterio de:', '["Innovación","Materia prima","Motivación"]'::jsonb, 0, 'Evaluar qué tan novedosa es la idea corresponde al criterio de innovación.'),
  ('q54', 3, 'concepto', null, null, null, 'Preguntarse si existen suficientes personas interesadas en comprar el producto corresponde al criterio de:', '["Mercado","Conocimiento técnico","Motivación"]'::jsonb, 0, 'Evaluar la demanda potencial corresponde al criterio de mercado.'),
  ('q55', 3, 'concepto', null, null, null, 'Preguntarse si el equipo sabe cómo elaborar el producto corresponde al criterio de:', '["Conocimiento técnico","Mercado","Innovación"]'::jsonb, 0, 'Evaluar si el equipo domina el proceso de elaboración corresponde al criterio de conocimiento técnico.'),
  ('q56', 3, 'caso', 'Dos estudiantes quieren hacer velas artesanales, pero ninguno sabe cómo derretir y verter la cera de forma segura.', null, null, '¿Qué criterio de selección de ideas está fallando en este caso?', '["Conocimiento técnico","Motivación","Mercado"]'::jsonb, 0, 'Les falta el conocimiento técnico necesario para elaborar el producto de forma segura.'),
  ('q57', 3, 'concepto', null, null, null, 'Antes de generar una idea de negocio, lo primero que debe identificar el equipo es:', '["Una necesidad real de las personas","El logo de la empresa","El precio al que se venderá el producto"]'::jsonb, 0, 'Toda buena idea de negocio parte de identificar una necesidad real del cliente.'),
  ('q58', 3, 'caso', 'En la soda del colegio no venden opciones saludables, así que un grupo decide preparar y vender frutas picadas en vasos.', null, null, '¿Qué hicieron principalmente para generar esta idea?', '["Identificar una necesidad insatisfecha del mercado","Copiar un producto de otro país","Reducir sus costos de producción"]'::jsonb, 0, 'Partieron de una necesidad real que no estaba siendo atendida en su colegio.'),
  ('q59', 3, 'concepto', null, null, null, 'Si dos equipos venden el mismo tipo de pulseras, lo que puede diferenciar a uno del otro ante el cliente es:', '["Su propuesta de valor","Vender al precio más bajo aunque genere pérdidas","Usar exactamente los mismos materiales y diseño"]'::jsonb, 0, 'La propuesta de valor explica por qué un cliente elegiría un producto sobre otro similar.'),
  ('q60', 4, 'concepto', null, null, null, 'Mejorar el prototipo varias veces con base en la retroalimentación recibida se llama:', '["Mejora iterativa","Producción en serie","Registro de marca"]'::jsonb, 0, 'Ajustar el prototipo repetidamente según los comentarios recibidos es la mejora iterativa.'),
  ('q61', 4, 'caso', 'Después de probar su primer diseño de bolso, el equipo cambió el tipo de tela porque los usuarios dijeron que era muy rígida.', null, null, '¿Qué están haciendo?', '["Aplicando una mejora iterativa al prototipo","Haciendo un estudio de costos del producto","Iniciando la producción final en serie"]'::jsonb, 0, 'Ajustar el diseño según la opinión de los usuarios es una mejora iterativa.'),
  ('q62', 4, 'concepto', null, null, 'prueba', 'Una ventaja de construir un prototipo sencillo antes de producir en masa es que:', '["Permite probar la idea con poca inversión","Garantiza que el producto final no tendrá fallas","Permite venderlo de inmediato al precio final"]'::jsonb, 0, 'El prototipo permite validar la idea sin arriesgar mucho dinero desde el inicio.'),
  ('q63', 4, 'caso', 'El equipo hizo solo 3 unidades de prueba de su producto antes de decidir producir 50 para la feria.', null, null, '¿Por qué es útil hacer esto primero?', '["Para validar la idea antes de invertir en mayor cantidad","Para cumplir un requisito de inscripción de la feria","Para vender las 3 unidades de inmediato"]'::jsonb, 0, 'Probar en pequeña escala permite corregir errores antes de una producción mayor.'),
  ('q64', 4, 'concepto', null, null, null, 'Preguntar a posibles clientes qué mejorarían del producto es un ejemplo de:', '["Recoger retroalimentación","Realizar un estudio de costos","Fijar el precio de venta"]'::jsonb, 0, 'Consultar la opinión de los clientes sobre el producto es recoger retroalimentación.'),
  ('q65', 4, 'caso', 'Varios compañeros probaron el prototipo del llavero y señalaron que el broche se abría con facilidad; el equipo lo cambió antes de la feria.', null, null, '¿Qué beneficio obtuvo el equipo al probar el prototipo?', '["Detectar y corregir una falla antes de vender el producto final","Aumentar el precio del producto","Producir más unidades en menos tiempo"]'::jsonb, 0, 'Probar el prototipo permitió encontrar y corregir un problema antes de la venta.'),
  ('q66', 4, 'concepto', null, null, null, 'Para construir un primer prototipo, generalmente conviene usar:', '["Materiales accesibles y de bajo costo","Materiales de la mejor calidad aunque sean muy costosos","Los mismos materiales de la producción final en gran cantidad"]'::jsonb, 0, 'El prototipo busca probar la idea sin una inversión grande, por eso conviene usar materiales accesibles.'),
  ('q67', 4, 'caso', 'El primer prototipo de la crema hidratante olía muy fuerte, así que el equipo probó tres fragancias distintas antes de escoger la definitiva.', null, null, '¿Qué proceso están aplicando?', '["Prueba y mejora del prototipo","Presentación final del producto","Cálculo del costo unitario"]'::jsonb, 0, 'Probar variantes y elegir la mejor es parte del proceso de prueba y mejora del prototipo.'),
  ('q68', 4, 'concepto', null, null, null, 'Si un prototipo no funciona como se esperaba, lo más útil para el equipo es:', '["Analizar qué falló y ajustarlo","Producirlo igual y corregir las fallas después de venderlo","Empezar de cero con una idea totalmente distinta"]'::jsonb, 0, 'Un prototipo fallido es una oportunidad de aprendizaje, no una razón para abandonar el proyecto.'),
  ('q69', 4, 'concepto', null, null, null, 'La principal diferencia entre un prototipo y el producto final es que el prototipo:', '["Se hace para probar y aún puede cambiar","Ya no admite ninguna modificación","Se vende directamente al público sin pruebas"]'::jsonb, 0, 'El prototipo es una versión de prueba, pensada para ajustarse antes de llegar al producto final.'),
  ('q70', 4, 'caso', 'Antes de decidir el sabor definitivo de sus galletas, el equipo hizo tres versiones y las repartió para que sus compañeros votaran.', null, null, '¿Qué herramienta utilizaron?', '["Una prueba de prototipo con usuarios reales","Un estudio de costos","Un informe final"]'::jsonb, 0, 'Repartir versiones del producto para recibir opiniones es una prueba de prototipo con usuarios.'),
  ('q71', 5, 'concepto', null, null, null, 'La ganancia de un producto se calcula como:', '["Precio de venta menos costo unitario","Precio de venta más costo unitario","Costo unitario dividido entre dos"]'::jsonb, 0, 'La ganancia es lo que queda después de restar el costo al precio de venta.'),
  ('q72', 5, 'caso', 'Un llavero cuesta ₡150 producirlo y se vende en ₡250.', null, null, '¿Cuál es la ganancia por unidad?', '["₡100","₡250","₡400"]'::jsonb, 0, 'Ganancia = precio de venta − costo = 250 − 150 = ₡100.'),
  ('q73', 5, 'concepto', null, null, null, 'El tiempo que el equipo invierte en elaborar el producto se considera parte de:', '["El costo de mano de obra","La ganancia","El precio de venta"]'::jsonb, 0, 'El trabajo invertido en producir el bien forma parte del costo de mano de obra.'),
  ('q74', 5, 'caso', 'El equipo gastó ₡3 000 en materiales y ₡1 000 en transporte para producir 10 pulseras.', null, 'dinero', '¿Cuál es el costo unitario de cada pulsera?', '["₡400","₡300","₡3 000"]'::jsonb, 0, 'Costo total = 3 000 + 1 000 = ₡4 000; costo unitario = 4 000 ÷ 10 = ₡400.'),
  ('q75', 5, 'concepto', null, null, null, 'El precio de venta de un producto debe cubrir al menos:', '["El costo unitario y dejar una ganancia","Solo el costo de los materiales","El precio de la competencia, sin importar el costo"]'::jsonb, 0, 'Un precio bien fijado cubre el costo de producir y además deja una ganancia razonable.'),
  ('q76', 5, 'caso', 'Un grupo vende su producto exactamente al mismo precio que le costó producirlo, sin agregar nada más.', null, null, '¿Qué consecuencia tiene esto para el equipo?', '["No obtienen ninguna ganancia","Recuperan lo invertido y además ganan","Pierden todo el dinero invertido"]'::jsonb, 0, 'Vender al mismo precio del costo significa que no queda ninguna ganancia para el equipo.'),
  ('q77', 5, 'concepto', null, null, null, 'Calcular bien los costos antes de fijar el precio permite principalmente:', '["Evitar vender con pérdidas","Garantizar que se venderán todas las unidades","Reducir automáticamente los gastos de producción"]'::jsonb, 0, 'Conocer los costos evita fijar un precio tan bajo que genere pérdidas.'),
  ('q78', 5, 'caso', 'Sofía sumó lo gastado en tela, hilo y botones para saber cuánto le costó hacer cada bolso.', null, null, '¿Qué está calculando Sofía?', '["El costo de producción de su producto","Su plan de ventas","Su propuesta de valor"]'::jsonb, 0, 'Sumar los gastos de materiales para un producto es calcular su costo de producción.'),
  ('q79', 5, 'concepto', null, null, null, 'Si se produce una mayor cantidad de unidades comprando materiales al por mayor, el costo unitario generalmente:', '["Puede disminuir","Siempre aumenta al doble","No tiene ninguna relación con la cantidad producida"]'::jsonb, 0, 'Comprar materiales al por mayor suele reducir el costo por unidad producida.'),
  ('q80', 5, 'caso', 'Un equipo cobra ₡800 por una pulsera que le costó ₡500 producir.', null, null, '¿Cuál es la ganancia por unidad?', '["₡300","₡500","₡800"]'::jsonb, 0, 'Ganancia = 800 − 500 = ₡300 por pulsera vendida.'),
  ('q81', 6, 'concepto', null, null, null, 'Dar a probar una pequeña porción del producto antes de comprarlo es una estrategia llamada:', '["Degustación","Combo o paquete promocional","Promoción por tiempo limitado"]'::jsonb, 0, 'Ofrecer una muestra para probar el producto es una degustación.'),
  ('q82', 6, 'caso', 'Antes de vender sus galletas en la feria, el equipo repartió pequeños trozos gratis para que la gente las probara.', null, null, '¿Qué estrategia de venta aplicaron?', '["Degustación","Combo o paquete promocional","Promoción por tiempo limitado"]'::jsonb, 0, 'Repartir una pequeña muestra gratuita del producto es una degustación.'),
  ('q83', 6, 'concepto', null, null, null, 'Definir cuántas unidades se espera vender en la feria corresponde a:', '["La meta de ventas","El presupuesto de gastos","El costo unitario"]'::jsonb, 0, 'Establecer una cantidad esperada de ventas es fijar la meta de ventas.'),
  ('q84', 6, 'concepto', null, null, null, 'Calcular cuánto dinero se necesita para producir y promocionar el producto antes de venderlo es elaborar:', '["Un presupuesto","Una meta de ventas","Un estudio de mercado"]'::jsonb, 0, 'Estimar los gastos necesarios antes de vender es elaborar un presupuesto.'),
  ('q85', 6, 'caso', 'El equipo definió que necesitaba vender al menos 40 unidades para cubrir sus costos y obtener alguna ganancia.', null, null, '¿Qué están definiendo?', '["Su meta de ventas","Su presupuesto de gastos","Su propuesta de valor"]'::jsonb, 0, 'Fijar una cantidad mínima a vender para cubrir costos es establecer una meta de ventas.'),
  ('q86', 6, 'concepto', null, null, null, 'Un producto pensado para estudiantes de secundaria tiene como mercado meta principal a:', '["Los propios estudiantes de secundaria","Cualquier persona sin distinción","Únicamente los profesores"]'::jsonb, 0, 'El mercado meta es el grupo específico al que está dirigido el producto.'),
  ('q87', 6, 'caso', 'Un equipo vende accesorios deportivos y decide promocionarlos principalmente entre compañeros que practican algún deporte.', null, null, '¿Qué están haciendo?', '["Enfocarse en su mercado meta","Vender a todo el público sin distinción","Aplicar una promoción por tiempo limitado"]'::jsonb, 0, 'Dirigir la promoción al grupo con más probabilidad de comprar es enfocarse en el mercado meta.'),
  ('q88', 6, 'concepto', null, 'Descuento solo por hoy', 'megafono', 'Anunciar esta frase en el negocio es un ejemplo de:', '["Promoción por tiempo limitado","Degustación","Combo o paquete promocional"]'::jsonb, 0, 'Ofrecer un beneficio válido por poco tiempo es una promoción por tiempo limitado.'),
  ('q89', 6, 'caso', 'El equipo diseñó un afiche colorido y lo colocó en la entrada del colegio antes de la feria para que más personas conocieran su producto.', null, null, '¿Qué están haciendo?', '["Promocionando su producto","Haciendo un estudio de mercado","Definiendo su meta de ventas"]'::jsonb, 0, 'Dar a conocer el producto antes de la venta mediante un afiche es una acción de promoción.'),
  ('q90', 6, 'concepto', null, 'Lleve 2 productos por el precio de 1.5', null, 'Ofrecer esta frase a los clientes es una estrategia de venta llamada:', '["Combo o paquete promocional","Degustación","Promoción por tiempo limitado"]'::jsonb, 0, 'Agrupar productos con un beneficio en el precio es un combo o paquete promocional.'),
  ('q91', 7, 'concepto', null, null, null, 'Además del proceso y los resultados, el informe final también debe reflejar:', '["Los aprendizajes y dificultades enfrentadas","Únicamente las fotos del producto terminado","Solo los resultados económicos de las ventas"]'::jsonb, 0, 'Un buen informe final documenta también lo aprendido y los retos superados.'),
  ('q92', 7, 'caso', 'En su informe, el equipo explicó que el mayor reto fue conseguir materiales reciclados a tiempo.', null, null, '¿Qué refleja esta parte del informe?', '["Un aprendizaje del proceso","El cálculo de costos","La propuesta de valor"]'::jsonb, 0, 'Contar las dificultades enfrentadas es parte de los aprendizajes del proceso.'),
  ('q93', 7, 'concepto', null, null, 'mercado', 'La Feria JOVEM permite a los equipos, entre otras cosas:', '["Practicar la venta real de su producto ante el público","Competir únicamente por ganar un premio","Entregar el informe final del proyecto"]'::jsonb, 0, 'La feria es un espacio para presentar y vender el producto ante público real.'),
  ('q94', 7, 'concepto', null, null, null, 'Al presentar el proyecto ante el público, es importante explicar el producto de forma:', '["Clara, ordenada y en poco tiempo","Extensa y con muchos tecnicismos","Enfocada únicamente en el precio del producto"]'::jsonb, 0, 'Una presentación efectiva es breve, clara y va directo a lo esencial del proyecto.'),
  ('q95', 7, 'caso', 'Antes de la feria, el equipo preparó respuestas para las preguntas más comunes que podrían hacerles los visitantes.', null, null, '¿Qué demuestra esta acción?', '["Preparación para la presentación del proyecto","Cálculo del costo unitario","Diseño del prototipo"]'::jsonb, 0, 'Anticiparse a las preguntas del público es parte de prepararse para presentar el proyecto.'),
  ('q96', 7, 'concepto', null, null, null, 'Recibir comentarios de los visitantes y jueces durante la feria sirve principalmente para:', '["Aprender y mejorar el proyecto a futuro","Comprobar que el proyecto ya no necesita cambios","Cambiar el precio de venta de inmediato"]'::jsonb, 0, 'La retroalimentación de la feria es una oportunidad para seguir mejorando el proyecto.'),
  ('q97', 7, 'caso', 'Al final de la feria, el equipo anotó qué les dijeron los visitantes sobre su producto para tomarlo en cuenta en el futuro.', null, null, '¿Qué están haciendo?', '["Registrando la retroalimentación para mejoras futuras","Realizando un estudio de mercado","Calculando su costo unitario"]'::jsonb, 0, 'Anotar los comentarios recibidos para mejorar después es registrar retroalimentación.'),
  ('q98', 7, 'concepto', null, null, null, 'Usar un afiche o stand ordenado y atractivo durante la feria ayuda principalmente a:', '["Captar la atención del público y comunicar mejor el proyecto","Garantizar que se venderá todo el producto","Reemplazar la explicación oral del proyecto"]'::jsonb, 0, 'Un stand ordenado y atractivo facilita que el público se acerque y entienda el proyecto.'),
  ('q99', 7, 'caso', 'Un equipo practicó su presentación frente a sus compañeros de clase varias veces antes del día de la feria.', null, null, '¿Cuál era el objetivo principal de esto?', '["Ganar confianza y fluidez al presentar","Memorizar el informe final palabra por palabra","Cumplir con un requisito de inscripción de la feria"]'::jsonb, 0, 'Ensayar la presentación ayuda a ganar seguridad y a comunicar mejor el proyecto el día de la feria.'),
  ('q100', 7, 'concepto', null, null, null, 'Presentar el producto en la feria y entregar el informe final representa:', '["El cierre del proceso de emprendimiento del proyecto JOVEM","El primer paso para generar la idea de negocio","La construcción del prototipo inicial"]'::jsonb, 0, 'La presentación final y el informe cierran el ciclo del proyecto emprendedor JOVEM.')
