-- ============================================================================
-- JOVEM Practica — Datos iniciales
-- Generado desde el prototipo: 100 preguntas, 7 unidades.
-- ============================================================================

-- Unidades
on conflict (id) do update set name = excluded.name, short_name = excluded.short_name;

-- Configuración de prácticas (fila única)
values (true, 80, 30, 70) on conflict (id) do nothing;

-- Banco de preguntas
on conflict (legacy_id) do update set
  unit_id = excluded.unit_id, type = excluded.type, scenario = excluded.scenario,
  example = excluded.example, image = excluded.image, stem = excluded.stem,
  options = excluded.options, correct_index = excluded.correct_index,
  explanation = excluded.explanation, updated_at = now();
